/// dashboard-grid: Rearrangeable dashboard with a stored layout
private struct DashboardGridExample0: View {
    struct Tile: Identifiable {
        let id: String
        let title: String
        let body: String
        var span: MonarchDashboardGridSpan = .one
    }

    private let tiles = [
        Tile(id: "figures", title: "Key figures", body: "128 open · 94% within target", span: .full),
        Tile(id: "load", title: "Team load", body: "12 open across 4 people.", span: .columns(2)),
        Tile(id: "activity", title: "Recent activity", body: "3 updates today."),
    ]
    @State private var layout: [String] = ["figures", "load", "activity"]
    @State private var isEditing = false

    var body: some View {
        VStack(alignment: .leading) {
            MonarchButton("Arrange", variant: isEditing ? .primary : .secondary, size: .sm) {
                isEditing.toggle()
            }
            MonarchDashboardGrid(
                tiles,
                layout: $layout,
                itemLabel: \.title,
                span: { $0.span },
                isEditing: isEditing,
                content: { tile in
                    MonarchWidget(tile.title) {
                        Text(tile.body).monarchTextStyle(.body)
                    }
                }
            )
            Text("Saved layout: \(layout.joined(separator: ", "))").monarchTextStyle(.caption)
        }
    }
}

