/// period-selector: Report periods with a custom range
private struct PeriodSelectorExample0: View {
    @State private var period = MonarchPeriod(MonarchPeriodPreset(rawValue: "30d") ?? .last30Days)

    /// The range the period resolves to, written as the web example's query line does.
    private var query: String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone(identifier: "UTC") ?? .gmt
        guard let range = period.resolved(today: Date(timeIntervalSince1970: 1_794_009_600), calendar: calendar) else { return "" }
        let format = Date.ISO8601FormatStyle(timeZone: calendar.timeZone).year().month().day()
        return "Query: \(range.lowerBound.formatted(format)) – \(range.upperBound.formatted(format))"
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            MonarchPeriodSelector(
                selection: $period,
                presets: ["7d", "30d", "90d", "this-month", "last-month", "custom"]
                    .compactMap { MonarchPeriodPreset(rawValue: $0) },
                today: Date(timeIntervalSince1970: 1_794_009_600),
                maximumDays: 366
            )
            Text(verbatim: query)
                .monarchTextStyle(.caption)
        }
    }
}

