/// relative-time: Relative and absolute
private struct RelativeTimeExample0: View {
    @Environment(\.monarchTheme) private var theme
    private let now = Date(timeIntervalSince1970: 1_793_707_200)
    private let locale = Locale(identifier: "en-GB")
    private func relative(_ date: Date) -> String {
        let formatter = RelativeDateTimeFormatter()
        formatter.locale = locale
        formatter.unitsStyle = .full
        return formatter.localizedString(for: date, relativeTo: now)
    }
    private var absolute: Date.FormatStyle {
        Date.FormatStyle(date: .abbreviated, time: .omitted, locale: locale, timeZone: TimeZone(identifier: "UTC") ?? .gmt)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space1) {
            Text("Edited \(Text(relative(Date(timeIntervalSince1970: 1_793_707_020))).underline(pattern: .dot))")
            Text("Synced \(Text(relative(Date(timeIntervalSince1970: 1_793_689_200))).underline(pattern: .dot))")
            Text("Renews \(Text(relative(Date(timeIntervalSince1970: 1_793_880_000))).underline(pattern: .dot))")
            Text("Created \(Date(timeIntervalSince1970: 1_790_251_200).formatted(absolute))")
        }
        .monarchTextStyle(.body)
    }
}

