/// widget: Loading, empty and failed
private struct WidgetExample1: View {
    @State private var isRetrying = false

    var body: some View {
        VStack {
            MonarchWidget("Approvals", state: .loading) { EmptyView() }
            MonarchWidget("Mentions", state: .empty("No mentions this week")) { EmptyView() }
            MonarchWidget("Revenue", state: .failed(), isRetrying: isRetrying, onRetry: { isRetrying = true }) {
                EmptyView()
            }
        }
    }
}
